window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-97c3a5aa2b68d8e1"]={"versions": [{"id": "FIG-97c3a5aa2b68d8e1", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Ablaufs eines Einzelschritts („Write Length“) innerhalb des E2E-Profils 4 (AUTOSAR Classic &amp; Adaptive Platform). Das Diagramm spezifiziert die Serialisierung der Längeninformation im Rahmen der Schutzfunktion <code>E2E_P04Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontextknoten: <code>E2E_P04Protect()</code> mit Call-Behavior-Symbol\n</li><li>Startknoten (Initial Node)\n</li><li>Aktionszustand: <code>Copy 2-byte Length on bytes Data[Offset...Offset+1] in Big Endian order</code>\n</li><li>Endknoten (Activity Final Node)\n</li><li>Datenentitäten/Schnittstellenparameter: Quellwert <code>Length</code> (2 Byte), Zielarray <code>Data[]</code>, Array-Index <code>Offset</code> (Byte-Offset)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in die Teilaktivität über den Initialknoten.\n</li><li>Ausführung der Aktion: Das 2 Byte lange Längenfeld (<code>Length</code>) wird ab der Byteposition <code>Offset</code> bis <code>Offset+1</code> im Big-Endian-Format in das Byte-Array <code>Data</code> geschrieben.\n</li><li>Kontrollflussübergang zum Activity Final Node und Beendigung des Schritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Implementierung der Funktion <code>E2E_P04Protect()</code> muss die 16-Bit-Längenangabe zwingend im Big-Endian-Format (Most Significant Byte zuerst) an <code>Data[Offset]</code> und das Least Significant Byte an <code>Data[Offset+1]</code> ablegen. Es ist sicherzustellen, dass der Speicherbereich <code>Data</code> mindestens die Größe <code>Offset + 2</code> umfasst, um Pufferüberläufe zu verhindern.</p>"}, {"id": "FIG-1c9c8c93ba99d6a4", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Ablaufs des Einzelschritts „Write Length“ innerhalb des E2E-Profils 4 (AUTOSAR Classic &amp; Adaptive Platform). Das Diagramm spezifiziert die Serialisierung der Längeninformation im Kontext der Funktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontextknoten: <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>, jeweils mit Call-Behavior-Symbol\n</li><li>Startknoten (Initial Node)\n</li><li>Aktionszustand: <code>Copy 2-byte Length on bytes Data[Offset...Offset+1] in Big Endian order</code>\n</li><li>Endknoten (Activity Final Node)\n</li><li>Datenentitäten/Schnittstellenparameter: Quellwert <code>Length</code> (2 Byte), Zielarray <code>Data[]</code>, Array-Index <code>Offset</code> (Byte-Offset)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in die Teilaktivität über den Initialknoten.\n</li><li>Ausführung der Aktion: Das 2 Byte lange Längenfeld (<code>Length</code>) wird ab der Byteposition <code>Offset</code> bis <code>Offset+1</code> im Big-Endian-Format in das Byte-Array <code>Data</code> geschrieben.\n</li><li>Kontrollflussübergang zum Activity Final Node und Beendigung des Schritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Implementierung der Funktionen <code>E2E_P04Protect()</code> sowie <code>E2E_P04Forward()</code> muss die 16-Bit-Längenangabe zwingend im Big-Endian-Format (Most Significant Byte zuerst) an <code>Data[Offset]</code> und das Least Significant Byte an <code>Data[Offset+1]</code> ablegen. Es ist sicherzustellen, dass der Speicherbereich <code>Data</code> mindestens die Größe <code>Offset + 2</code> umfasst, um Pufferüberläufe zu verhindern.</p>"}], "trans": [{"from": "FIG-97c3a5aa2b68d8e1", "to": "FIG-1c9c8c93ba99d6a4", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kontext-Zuordnung: <code>E2E_P04Forward()</code> als zusätzlicher Aktivitäts-/Funktionskontext (Call-Behavior-/Invocation-Symbol) neben <code>E2E_P04Protect()</code> ergänzt.\n</li></ul>"}]};
